-- Explicit mock contract for isolated script logic, not real transaction tests.
function string.findi(s, pattern) return string.find(string.lower(s), string.lower(pattern), 1, true) end
calls = { rewards={}, factions={}, speech={}, spells={}, cash={}, exp=0, returns=0, signals={}, zone_flags={}, depops=0 }
character = { class=4, level=50 }
local function strict(t, label)
 return setmetatable(t, {__index=function(_,k) error('Unmocked '..label..' API: '..k) end})
end
other = strict({
 GetCleanName=function() return "Reviewer" end, GetName=function() return 'Reviewer' end, GetID=function() return 42 end,
 GetClass=function() return character.class end, Class=function() return character.class end,
 GetLevel=function() return character.level end,
 GetClassName=function() return character.class==4 and 'Ranger' or 'Warrior' end,
 GetFaction=function() return 1 end,
 SummonItem=function(_,id,quantity) calls.rewards[id]=(calls.rewards[id] or 0)+(quantity or 1) end,
 Faction=function(_,id,value) calls.factions[id]=(calls.factions[id] or 0)+value end,
 AddEXP=function(_,value) calls.exp=calls.exp+value end,
 QuestReward=function(_,npc,c,s,g,p,item,xp) if type(c)=="table" then item=c.itemid;xp=c.exp or 0 elseif (c or 0)+(s or 0)+(g or 0)+(p or 0)>0 then table.insert(calls.cash,{c or 0,s or 0,g or 0,p or 0}) end; calls.exp=calls.exp+(xp or 0); if item and item~=0 then calls.rewards[item]=(calls.rewards[item] or 0)+1 end end,
 Ding=function() end,
 GiveCash=function(_,c,s,g,p) table.insert(calls.cash,{c,s,g,p}) end,
},'character')
npc = strict({
 Say=function(_,text) table.insert(calls.speech,text) end,
 Emote=function(_,text) table.insert(calls.speech,text) end,
 CastSpell=function(_,id,target) table.insert(calls.spells,{id,target}) end,
 CheckHandin=function(_,client,available,required,instances)
  for id,n in pairs(required) do if (remaining[id] or 0)<n then return false end end
  for id,n in pairs(required) do remaining[id]=remaining[id]-n end
  return true
 end,
 ReturnHandinItems=function() calls.returns=calls.returns+1 end,
},'NPC')
eq = strict({handin=function(required) return npc:CheckHandin(other,remaining,required,{}) end,depop_with_timer=function() calls.depops=calls.depops+1 end,set_zone_flag=function(id) table.insert(calls.zone_flags,id) end,signal=function(id,value,delay) table.insert(calls.signals,{id,value,delay or 0}) end,ChooseRandom=function(...) return (select(character.choice or 1,...)) end},'eq')
function say(text) event_say({self=npc,other=other,message=text}) end
function trade(ids,coins)
 remaining={}; local t={self=npc,other=other,platinum=0,gold=0,silver=0,copper=0}
 for i=1,4 do
  local id=ids[i] or 0
  t['item'..i]={valid=id~=0,GetID=function() return id end}
  if id~=0 then remaining[id]=(remaining[id] or 0)+1 end
 end
 for k,v in pairs(coins or {}) do t[k]=v;remaining[k]=v end
 event_trade({self=npc,other=other,trade=t})
end
function equal(actual,expected,label) assert(actual==expected,(label or 'value')..': expected '..tostring(expected)..', got '..tostring(actual)) end
function reward(id,n) equal(calls.rewards[id] or 0,n,'reward '..id) end
function faction(id,n) equal(calls.factions[id] or 0,n,'faction '..id) end

package.preload["items"]=function()
local items = {}

function items.check_turn_in(trade, trade_check)
    local handin_data = {};
    local index = 1;
    for key, value in pairs(trade) do
        if (key:findi("item")) then
            local item_id = value:GetID()
            if item_id ~= nil and item_id ~= 0 then
                if handin_data[item_id] ~= nil then
                    handin_data[item_id] = handin_data[item_id] + 1
                else
                    handin_data[item_id] = 1
                end
            end
        end
    end

    local item_data = {};
    for x = 1, 4 do
        local inst = trade["item" .. x];
        if (inst.valid) then
            item_data[x] = inst
        end
    end

    local required_data = {}
    for i = 1, 4 do
        local key = "item" .. i;
        local item_id = trade_check[key]

        if item_id ~= nil and item_id ~= 0 then
            if required_data[item_id] ~= nil then
                required_data[item_id] = required_data[item_id] + 1
            else
                required_data[item_id] = 1
            end
        end
    end

	local currencies = { "platinum", "gold", "silver", "copper" }

	-- Loop through each currency and check the corresponding key in trade_check
	for _, currency in ipairs(currencies) do
		if trade_check[currency] ~= nil and trade_check[currency] ~= 0 then
			-- Process the currency value
			local amount = trade_check[currency]
			required_data[currency] = amount
			-- You can perform your logic here, like adding to total or comparing values
		end
	end

	for _, currency in ipairs(currencies) do
		if trade[currency] ~= nil and trade[currency] ~= 0 then
			handin_data[currency] = trade[currency]
		end 
	end

    if (trade.self) then
        return trade.self:CheckHandin(trade.other, handin_data, required_data, item_data);
    else
        return false
    end
end

function items.return_items(npc, client, trade, text)
	npc:ReturnHandinItems(client);
end

function items.return_bot_items(bot, client, trade, text)
	text = text or true;
	local returned = false;
	for i = 1, 8 do
		local inst = trade["item" .. i];
		if (inst.valid) then
			client:PushItemOnCursor(inst);
			returned = true;
		end
	end

	local money = false;
	if (trade.platinum ~= 0) then
		returned = true;
		money = true;
	end

	if (trade.gold ~= 0) then
		returned = true;
		money = true;
	end

	if (trade.silver ~= 0) then
		returned = true;
		money = true;
	end

	if (trade.copper ~= 0) then
		returned = true;
		money = true;
	end

	if (money) then
		client:AddMoneyToPP(trade.copper, trade.silver, trade.gold, trade.platinum, true);
	end

	if (text and returned) then
		bot:OwnerMessage("I have no need for this, you can have it back.")
	end

	return returned;
end

function items.check_bot_turn_in(trade, trade_check)
	--create trade_return table == trade
	--shallow copy
	local trade_return = {};
	for key, value in pairs(trade) do
		trade_return[key] = value;
	end

	--for every item in trade_check check trade_return
		--if item exists in trade_return then 
			--remove that item from trade_return
		--else
			--failure
	for i = 1, 8 do
		local key = "item" .. i;
		if(trade_check[key] ~= nil and trade_check[key] ~= 0) then
			local found = false;
			for j = 1, 8 do
				local inst = trade_return["item" .. j];			
				if(inst.valid and trade_check[key] == inst:GetID()) then
					trade_return["item" .. j] = ItemInst();
					found = true;
					break;
				end
			end

			if(not found) then
				return false;
			end
		end
	end

	--convert our money into copper then check that we have enough then convert change back
	local trade_check_money = 0;
	local return_money = 0;

	if(trade_check["platinum"] ~= nil and trade_check["platinum"] ~= 0) then
		trade_check_money = trade_check_money + (trade_check["platinum"] * 1000);
	end

	if(trade_check["gold"] ~= nil and trade_check["gold"] ~= 0) then
		trade_check_money = trade_check_money + (trade_check["gold"] * 100);
	end

	if(trade_check["silver"] ~= nil and trade_check["silver"] ~= 0) then
		trade_check_money = trade_check_money + (trade_check["silver"] * 10);
	end

	if(trade_check["copper"] ~= nil and trade_check["copper"] ~= 0) then
		trade_check_money = trade_check_money + trade_check["copper"];
	end

	return_money = return_money + trade_return["platinum"] * 1000 + trade_return["gold"] * 100;
	return_money = return_money + trade_return["silver"] * 10 + trade_return["copper"];

	if(return_money < trade_check_money) then
		return false;
	else
		return_money = return_money - trade_check_money;
	end

	--replace trade with trade_return
	trade.item1 = trade_return.item1;
	trade.item2 = trade_return.item2;
	trade.item3 = trade_return.item3;
	trade.item4 = trade_return.item4;
	trade.item5 = trade_return.item5;
	trade.item6 = trade_return.item6;
	trade.item7 = trade_return.item7;
	trade.item8 = trade_return.item8;

	trade.platinum = math.floor(return_money / 1000);
	return_money = return_money - (trade.platinum * 1000);

	trade.gold = math.floor(return_money / 100);
	return_money = return_money - (trade.gold * 100);

	trade.silver = math.floor(return_money / 10);
	return_money = return_money - (trade.silver * 10);

	trade.copper = return_money;
	return true;
end

return items;
end
